import 'package:cana_cabana/models/metafield.dart';
import 'package:freezed_annotation/freezed_annotation.dart';
import 'package:flutter/foundation.dart';

// required: associates our `main.dart` with the code generated by Freezed
part 'variants.freezed.dart';
// optional: Since our Person class is serializable, we must add this line.
// But if Person was not serializable, we could skip it.

@freezed
class Variant with _$Variant {
  const factory Variant({
    required String title,
    required int id,
    required int productId,
    required String description,
    required List<Metafield> metafields,
  }) = _Variant;
  factory Variant.fromJson(Map<String, dynamic> json) {
    List metafieldsJson = json["metafields"];
    List<Metafield> metafields = [];
    for (var element in metafieldsJson) {
      metafields.add(Metafield.fromJson(element as Map<String, dynamic>));
    }
    return Variant(
      title: json["title"],
      id: json["id"],
      productId: json["parent_id"],
      description: json["description"],
      metafields: metafields,
    );
  }
}
// This file is "main.dart"
